      { label: 'td', content: "<code>transform</code>" },
      { label: 'td', content: "<code>(data: object) => object</code>" },
      { label: 'td', content: "原样返回" },
      { label: 'td', content: "发送与体积估算前执行的幂等载荷变换" }
